import{_ as e,o as a,c as s,a5 as n}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"1. What C Is and Why It Still Matters","description":"The Little Book of C — 1. What C Is and Why It Still Matters","frontmatter":{"title":"1. What C Is and Why It Still Matters","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Getting Started"],"description":"The Little Book of C — 1. What C Is and Why It Still Matters","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":1,"sidebarWeight":1,"lang":"en-US","alternateEn":"/posts/c教程/en-US/01-Getting Started/001-What C Is and Why It Still Matters","alternateZh":"/posts/c教程/zh-CN/01-入门/001-What C Is and Why It Still Matters"},"headers":[],"relativePath":"posts/c教程/en-US/01-Getting Started/001-What C Is and Why It Still Matters.md","filePath":"posts/c教程/en-US/01-Getting Started/001-What C Is and Why It Still Matters.md","lastUpdated":1790163617000}'),o={name:"posts/c教程/en-US/01-Getting Started/001-What C Is and Why It Still Matters.md"};function i(r,t,l,h,p,d){return a(),s("div",null,[...t[0]||(t[0]=[n(`<p>[中文版本](/posts/c教程/zh-CN/01-入门/001-What C Is and Why It Still Matters)</p><p>C is the language that sits closest to the machine while still feeling human to write. It’s not the newest or the easiest, but it’s one of the most powerful. Every modern operating system, compiler, and database has a core written in C, from Linux and Git to Python’s interpreter and even parts of your browser.</p><p>Learning C gives you something no other language can: an understanding of how computers actually work. You’ll see how memory is managed, how data moves, how the CPU runs your code, and how everything you write turns into tiny instructions that the machine understands.</p><p>C teaches discipline. There’s no garbage collector or safety net. You decide when to allocate memory, when to free it, and what happens when you forget. You learn precision and control, the same skills that make great programmers in any language.</p><h4 id="tiny-code" tabindex="-1">Tiny Code <a class="header-anchor" href="#tiny-code" aria-label="Permalink to &quot;Tiny Code&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Hello, C World!\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Run this and you’ve done what every C programmer starts with, printing your first line of text to the screen. It’s small, but it carries the spirit of C: direct, explicit, and clear.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>C is the foundation of all systems programming. When you understand it, higher-level languages make more sense. You’ll see why compilers work the way they do, why memory errors happen, and how performance decisions ripple through an entire program.</p><p>Even if you never write production C code, the mindset it builds, careful reasoning, attention to detail, respect for the machine, will shape how you write code in any language.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><p>Install a C compiler like<code>gcc</code> or<code>clang</code>.</p><p>Save the code above into a file named<code>hello.c</code>.</p><p>Compile it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc hello.c -o hello</span></span></code></pre></div><p>Run it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./hello</span></span></code></pre></div><p>Modify the message and try printing more lines. You’ve just built your first C program.</p>`,18)])])}const g=e(o,[["render",i]]);export{u as __pageData,g as default};
